SET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;
SQL;

// ── 6. Remove the trailing SET FOREIGN_KEY_CHECKS restore from schema.sql ────
//    (we'll add it back at the very end with the extensions block)
$schema = preg_replace('/\nSET FOREIGN_KEY_CHECKS=@OLD_FOREIGN_KEY_CHECKS;\s*$/', '', $schema);

// ── 7. Build final output ─────────────────────────────────────────────────────
$header  = "-- =============================================================\n";
$header .= "-- Shena Companion Welfare Association -- PRODUCTION DATABASE\n";
$header .= "-- Generated : " . date('Y-m-d H:i:s') . "\n";
$header .= "-- Usage     : Import via cPanel -> phpMyAdmin -> Import tab\n";
$header .= "--             Create an empty database first, then import.\n";
$header .= "-- IMPORTANT : Update REPLACE_WITH_* placeholders and YOURDOMAIN.COM\n";
$header .= "--             before importing into production.\n";
$header .= "-- =============================================================\n\n";

$output = $header . $schema . $extensions;

file_put_contents($outputFile, $output);
echo "Generated: database/shena_production.sql (" . number_format(strlen($output)) . " bytes)\n";
